"""Generate the static site and identical legal pages; no deployment side effects."""
from pathlib import Path
from html import escape
import base64, hashlib, json

ROOT = Path(__file__).resolve().parent.parent
DATE = '2026-10-11'
CUSTOM_PRODUCT_PAGE_ID = 'fc80f820-a690-452a-95d4-76c93fce92d7'
