PROVIDER_TOKEN = '1329661'

def store_link(placement):
    return STORE + (f'&amp;pt={PROVIDER_TOKEN}&amp;ct=site_{placement}&amp;mt=8' if PROVIDER_TOKEN else '')

def cta(placement, label='View on the App Store', extra=''):
    return f'<a class="button {extra}" href="{store_link(placement)}">{label}<span aria-hidden="true">↗</span></a>'

def header():
    return '''<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><nav class="wrap nav" aria-label="Main navigation">
<a class="brand" href="https://feedfare.app/" aria-label="FeedFare home"><img src="assets/app-icon-64.webp?v=build29" srcset="assets/app-icon-128.webp?v=build29 2x" width="38" height="38" alt="" decoding="async"><span translate="no">FeedFare</span></a>
<div class="nav-links"><a href="https://feedfare.app/#demo">Watch demo</a><a href="https://feedfare.app/#how-it-works">How it works</a><a href="https://feedfare.app/#faq">FAQ</a><a href="https://feedfare.app/support.html">Support</a></div>
''' + cta('navigation','Get FeedFare','button-small') + '</nav></header>'

def footer():
    return '''<footer class="footer"><div class="wrap"><div class="footer-top"><a class="brand" href="https://feedfare.app/"><img src="assets/app-icon-64.webp?v=build29" width="32" height="32" alt="" loading="lazy"><span translate="no">FeedFare</span></a><nav class="footer-links" aria-label="Footer navigation"><a href="https://feedfare.app/#about">About</a><a href="https://feedfare.app/support.html">Support</a><a href="https://feedfare.app/privacy-policy.html">Privacy</a><a href="https://feedfare.app/terms.html">Terms</a><a href="https://feedfare.app/press.html">Press kit</a><a href="https://nickrae.net">Made by Nick Rae ↗</a></nav></div><div class="footer-bottom"><span>© 2026 Nick Rae. A little movement. A better balance.</span><span>Made for your day, not your attention.</span></div></div></footer>'''

def page(title,description,path,body,schema=None,script=False,noindex=False):
    structured = json.dumps(schema,separators=(',',':'),ensure_ascii=False) if schema else ''
    digest = base64.b64encode(hashlib.sha256(structured.encode()).digest()).decode() if structured else ''
    script_policy = "'self'" + (f" 'sha256-{digest}'" if structured else '')
    policy = f"default-src 'none'; base-uri 'none'; object-src 'none'; script-src {script_policy}; style-src 'self'; img-src 'self'; media-src 'self'; font-src 'self'; connect-src 'none'; form-action 'none'; upgrade-insecure-requests"
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="{policy}">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="referrer" content="strict-origin-when-cross-origin">
<meta name="theme-color" content="#f5f6f9">
<title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}">
<link rel="canonical" href="https://feedfare.app/{path}">
<link rel="icon" href="assets/favicon.png?v=build29" type="image/png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png?v=build29">
<meta name="apple-itunes-app" content="app-id=6758923557">
<meta property="og:type" content="website"><meta property="og:url" content="https://feedfare.app/{path}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:image" content="https://feedfare.app/og-image.png?v=launch20261005"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="FeedFare — Walk first. Scroll later. The native app with example progress.">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title,quote=True)}"><meta name="twitter:description" content="{escape(description,quote=True)}"><meta name="twitter:image" content="https://feedfare.app/og-image.png?v=launch20261005">
{'<meta name="robots" content="noindex">' if noindex else ''}
<link rel="stylesheet" href="assets/site.css?v=20261011-press">
{'<script type="application/ld+json">'+structured+'</script>' if structured else ''}
{'<script src="assets/site.js?v=20261011" defer></script>' if script else ''}
</head><body id="top">{header()}{body}{footer()}</body></html>'''

def image(name,alt,hero=False):
    loading = 'fetchpriority="high"' if hero else 'loading="lazy"'
    return f'<img src="assets/{name}-native-480.webp" srcset="assets/{name}-native-480.webp 480w, assets/{name}-native-800.webp 800w" sizes="{("(max-width: 800px) 215px, 250px" if hero else "(max-width: 600px) 125px, 180px")}" width="480" height="1044" alt="{escape(alt,quote=True)}" {loading} decoding="async">'

