schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':'FeedFare','applicationCategory':'HealthApplication','operatingSystem':'iOS 17 or later; iPadOS 17 or later','url':'https://feedfare.app/','downloadUrl':STORE,'description':'Turn your daily steps into earned screen time for the apps you choose.','author':{'@type':'Person','name':'Nick Rae','url':'https://nickrae.net'}}
